1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Damage {
18	  itemType: string;
19	  amount: number;
20	}
21	
22	export interface ClaimStep {
23	  op: "claim";
24	  policy: number;
25	  incident: { cause: string; damages: Damage[] };
26	}
27	
28	export type Step = QuoteStep | ClaimStep;
29	
30	export interface Scenario {
31	  customer: Customer;
32	  steps: Step[];
33	}
34	
35	export type StepResult =
36	  | { premium: number }
37	  | { payout: number; remainingCap: number };
38	
39	export interface ScenarioResult {
40	  results: StepResult[];
41	}
42	
43	/**
44	 * Added at the very end of every premium, after all percentage modifiers, so
45	 * no surcharge or discount is ever computed on top of it.
46	 */
47	const PROCESSING_FEE = 5;
48	
49	/**
50	 * Rates are kept as exact numerator/denominator fractions rather than float
51	 * multipliers (10 / 100, never 1.1) so intermediate amounts stay exact and
52	 * only the final premium is rounded.
53	 */
54	const percent = (amount: number, rate: number): number => (amount * rate) / 100;
55	
56	/**
57	 * Both roundings go the MHPCO's way, and both are applied once, at the very end
58	 * of a calculation — never to an intermediate amount. The two are stated here as
59	 * a pair because that is the rule: it is one policy with two directions, and
60	 * which direction applies follows from who pays.
61	 */
62	const roundedUpForWhatTheCustomerPays = Math.ceil;
63	const roundedDownForWhatTheMHPCOPays = Math.floor;
64	
65	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
66	const CURSE_SURCHARGE_PERCENT = 50;
67	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
68	/**
69	 * Enchantment is read by two unrelated rules with different cut-offs: this one
70	 * charges a premium surcharge from 5 up, and REDUCED_REIMBURSEMENT_THRESHOLD
71	 * halves a claim from 8 up. Each threshold is named after the rule it gates so
72	 * the two cannot be mistaken for one shared notion of "highly enchanted".
73	 */
74	const ENCHANTMENT_SURCHARGE_THRESHOLD = 5;
75	const LOYALTY_DISCOUNT_PERCENT = 20;
76	const LOYALTY_THRESHOLD_YEARS = 2;
77	const FOLLOW_UP_DISCOUNT_PERCENT = 15;
78	
79	/**
80	 * Everything the pricing rules need to know about an item type lives here, so
81	 * that "what is a rune?" has a single answer. Components are the small parts
82	 * (runes, moonstones) that can be bought as a building block; main items
83	 * (swords, amulets, ...) never form a block.
84	 */
85	const ITEM_TYPES: Record<
86	  string,
87	  { unitPremium: number; insuranceValue: number; isComponent: boolean }
88	> = {
89	  sword: { unitPremium: 100, insuranceValue: 1000, isComponent: false },
90	  amulet: { unitPremium: 60, insuranceValue: 600, isComponent: false },
91	  staff: { unitPremium: 80, insuranceValue: 800, isComponent: false },
92	  potion: { unitPremium: 40, insuranceValue: 400, isComponent: false },
93	  rune: { unitPremium: 25, insuranceValue: 250, isComponent: true },
94	  moonstone: { unitPremium: 25, insuranceValue: 250, isComponent: true },
95	};
96	
97	/**
98	 * The single gate onto ITEM_TYPES, so that an item the MHPCO does not insure is
99	 * refused by name rather than surfacing as a stray TypeError somewhere downstream.
100	 */
101	const itemTypeOf = (type: string): (typeof ITEM_TYPES)[string] => {
102	  const itemType = ITEM_TYPES[type];
103	  if (itemType === undefined) {
104	    throw new Error(`unknown item type: ${type}`);
105	  }
106	  return itemType;
107	};
108	
109	/** A building block of 3 alike components is offered at this base premium. */
110	const COMPONENT_BLOCK_BASE_PREMIUM = 60;
111	const COMPONENT_BLOCK_SIZE = 3;
112	
113	/** Tallies how many items of each type a policy covers, e.g. [["rune", 3]]. */
114	const countByType = (items: Item[]): [string, number][] => {
115	  const counts = new Map<string, number>();
116	  for (const item of items) {
117	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
118	  }
119	  return [...counts];
120	};
121	
122	/**
123	 * Prices every item of one type together, because exactly 3 alike components
124	 * form a block charged as one. "Alike" means the same type, and the block does
125	 * not repeat: 4 or 7 runes are each priced per item.
126	 */
127	const basePremiumForType = (type: string, count: number): number => {
128	  const { unitPremium, isComponent } = itemTypeOf(type);
129	  return isComponent && count === COMPONENT_BLOCK_SIZE
130	    ? COMPONENT_BLOCK_BASE_PREMIUM
131	    : count * unitPremium;
132	};
133	
134	const sumOfBasePremiums = (items: Item[]): number =>
135	  countByType(items).reduce(
136	    (sum, [type, count]) => sum + basePremiumForType(type, count),
137	    0,
138	  );
139	
140	/**
141	 * A rule whose rate is ADDED to those of every other matching rule. Read with
142	 * filter+reduce: matching several rules charges for each.
143	 *
144	 * Distinct from ExclusiveRule<T> below, which has the same {appliesTo, rate}
145	 * shape but the opposite semantics. The two are separate named types rather
146	 * than one shared shape so that the reader — and the compiler — cannot mistake
147	 * a stacking table for a first-match-wins one.
148	 */
149	interface StackingRule<T> {
150	  appliesTo: (subject: T) => boolean;
151	  rate: number;
152	}
153	
154	/**
155	 * A rule that is an ALTERNATIVE to the others: the first match wins and the
156	 * rest are skipped. Read with find. Order is therefore meaningful — it encodes
157	 * precedence, and reordering the table changes results.
158	 */
159	interface ExclusiveRule<T> {
160	  appliesTo: (subject: T) => boolean;
161	  rate: number;
162	}
163	
164	/**
165	 * Item-specific modifiers: each applies to one item and is charged as a
166	 * percentage of THAT item's unit premium, never of the policy total.
167	 * They stack — an item matching several rules is charged for each.
168	 *
169	 * Unit premium, not the item's share of the policy base: the two differ only
170	 * for components inside a block of 3 (billed 60 G for three 25 G runes), and
171	 * no test pins down a surcharged component yet. Revisit when one does.
172	 */
173	const ITEM_MODIFIERS: StackingRule<Item>[] = [
174	  { appliesTo: (item) => item.cursed === true, rate: CURSE_SURCHARGE_PERCENT },
175	  {
176	    appliesTo: (item) =>
177	      (item.enchantment ?? 0) >= ENCHANTMENT_SURCHARGE_THRESHOLD,
178	    rate: HIGH_ENCHANTMENT_SURCHARGE_PERCENT,
179	  },
180	];
181	
182	const surchargeForItem = (item: Item): number =>
183	  ITEM_MODIFIERS.filter(({ appliesTo }) => appliesTo(item)).reduce(
184	    (sum, { rate }) => sum + percent(itemTypeOf(item.type).unitPremium, rate),
185	    0,
186	  );
187	
188	const sumOfItemSurcharges = (items: Item[]): number =>
189	  items.reduce((sum, item) => sum + surchargeForItem(item), 0);
190	
191	/**
192	 * Policy-wide modifiers: each is charged as a percentage of the POLICY BASE
193	 * premium (the sum of item base premiums, before any item surcharge), so no
194	 * modifier is ever computed on top of another. Discounts carry a negative rate.
195	 */
196	interface PolicyContext {
197	  customer: Customer;
198	  /** Quotes already issued to this customer earlier in the scenario. */
199	  previousContracts: number;
200	}
201	
202	const POLICY_MODIFIERS: StackingRule<PolicyContext>[] = [
203	  // Always applies: every item in a quote is treated as a first insurance,
204	  // regardless of how long the customer has been with the MHPCO.
205	  { appliesTo: () => true, rate: FIRST_INSURANCE_SURCHARGE_PERCENT },
206	  {
207	    // Negative rate: a discount is just a surcharge pointing the other way, so
208	    // it needs no separate code path and cannot stack onto another modifier.
209	    appliesTo: ({ customer }) =>
210	      customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS,
211	    rate: -LOYALTY_DISCOUNT_PERCENT,
212	  },
213	  {
214	    appliesTo: ({ previousContracts }) => previousContracts >= 1,
215	    rate: -FOLLOW_UP_DISCOUNT_PERCENT,
216	  },
217	];
218	
219	const sumOfPolicyAdjustments = (
220	  context: PolicyContext,
221	  policyBasePremium: number,
222	): number =>
223	  POLICY_MODIFIERS.filter(({ appliesTo }) => appliesTo(context)).reduce(
224	    (sum, { rate }) => sum + percent(policyBasePremium, rate),
225	    0,
226	  );
227	
228	const premiumFor = (context: PolicyContext, items: Item[]): number => {
229	  const policyBasePremium = sumOfBasePremiums(items);
230	  return roundedUpForWhatTheCustomerPays(
231	    policyBasePremium +
232	      sumOfItemSurcharges(items) +
233	      sumOfPolicyAdjustments(context, policyBasePremium) +
234	      PROCESSING_FEE,
235	  );
236	};
237	
238	/** A policy created by a quote step, tracked so later claims can draw on it. */
239	interface Policy {
240	  items: Item[];
241	  remainingCap: number;
242	}
243	
244	const DEDUCTIBLE_PER_DAMAGE = 100;
245	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
246	
247	const insuranceSumOf = (items: Item[]): number =>
248	  items.reduce((sum, item) => sum + itemTypeOf(item.type).insuranceValue, 0);
249	
250	const REDUCED_REIMBURSEMENT_THRESHOLD = 8;
251	const REDUCED_REIMBURSEMENT_PERCENT = 50;
252	
253	/** Reimbursed in full when no clause below claims the item. */
254	const FULL_REIMBURSEMENT_PERCENT = 100;
255	const DRAGON_MATERIAL = "dragon";
256	
257	/**
258	 * Clauses that change how much of a damage is reimbursed. Exclusive and ordered
259	 * by precedence, because clauses overlap (a highly enchanted dragon-material
260	 * item matches more than one) and they are alternatives — unlike the stacking
261	 * ITEM_MODIFIERS, which the {appliesTo, rate} shape would otherwise suggest.
262	 */
263	const REIMBURSEMENT_CLAUSES: ExclusiveRule<Item>[] = [
264	  {
265	    appliesTo: (item) =>
266	      (item.enchantment ?? 0) >= REDUCED_REIMBURSEMENT_THRESHOLD,
267	    rate: REDUCED_REIMBURSEMENT_PERCENT,
268	  },
269	  // Listed after the clause above so that a highly enchanted dragon item is
270	  // still reimbursed at 50 %. This entry yields exactly what the no-clause
271	  // default yields, so removing it would not change any current result — it is
272	  // here because the spec states dragon material as a rule, and because the
273	  // ordering is what makes the 50 % rule win.
274	  {
275	    appliesTo: (item) => item.material === DRAGON_MATERIAL,
276	    rate: FULL_REIMBURSEMENT_PERCENT,
277	  },
278	];
279	
280	const reimbursementRateFor = (item: Item): number =>
281	  REIMBURSEMENT_CLAUSES.find(({ appliesTo }) => appliesTo(item))?.rate ??
282	  FULL_REIMBURSEMENT_PERCENT;
283	
284	/**
285	 * Which insured item a damage entry is about. The counterpart to itemTypeOf:
286	 * both resolve a name to the thing it denotes, and both are the one place their
287	 * lookup happens — so the "not covered by the policy" and "more damage entries
288	 * than insured" rules have a single site to be enforced from.
289	 *
290	 * An item the policy does not cover is refused here, which also covers a damage
291	 * naming a type the MHPCO does not insure at all: neither is in the policy.
292	 */
293	const insuredItemFor = (damage: Damage, insuredItems: Item[]): Item => {
294	  const insuredItem = insuredItems.find(
295	    (item) => item.type === damage.itemType,
296	  );
297	  if (insuredItem === undefined) {
298	    throw new Error(
299	      `damaged item is not covered by the policy: ${damage.itemType}`,
300	    );
301	  }
302	  return insuredItem;
303	};
304	
305	/**
306	 * The clause is applied to the damage first; the deductible comes off whatever
307	 * the clause leaves.
308	 *
309	 * Takes the already-resolved item, so this is pure arithmetic over a damage and
310	 * the item it hit — mirroring basePremiumForType, which likewise prices an
311	 * already-resolved type rather than doing its own lookup.
312	 */
313	const payoutForDamage = (damage: Damage, damagedItem: Item): number =>
314	  percent(damage.amount, reimbursementRateFor(damagedItem)) -
315	  DEDUCTIBLE_PER_DAMAGE;
316	
317	/**
318	 * The contract a quote step issues: what it covers, and how much of its cap is
319	 * still available to later claims.
320	 */
321	const policyFor = (items: Item[]): Policy => ({
322	  items,
323	  remainingCap: CAP_MULTIPLE_OF_INSURANCE_SUM * insuranceSumOf(items),
324	});
325	
326	/**
327	 * What an incident is worth against a policy, as a pure calculation: each
328	 * damage is settled on its own (own clause, own deductible) and the results are
329	 * added up. Drawing this down from the policy's cap is the caller's job.
330	 */
331	const payoutForIncident = (
332	  incident: ClaimStep["incident"],
333	  insuredItems: Item[],
334	): number =>
335	  incident.damages.reduce(
336	    (sum, damage) =>
337	      sum + payoutForDamage(damage, insuredItemFor(damage, insuredItems)),
338	    0,
339	  );
340	
341	/**
342	 * Settles an incident against a policy and draws the payout down from its cap.
343	 * Mutates the policy, because what this claim consumes has to be visible to
344	 * every later claim on the same one.
345	 *
346	 * The cap is a ceiling, not just a running total: once it is exhausted a claim
347	 * is paid only what is left of it. Rounding happens once, here, after the clamp
348	 * — so per-damage amounts stay fractional (a multi-item incident is not rounded
349	 * once per damage) and the cap stays whole.
350	 */
351	const settleClaim = (
352	  policy: Policy,
353	  incident: ClaimStep["incident"],
354	): StepResult => {
355	  const payout = roundedDownForWhatTheMHPCOPays(
356	    Math.min(payoutForIncident(incident, policy.items), policy.remainingCap),
357	  );
358	  policy.remainingCap -= payout;
359	  return { payout, remainingCap: policy.remainingCap };
360	};
361	
362	/**
363	 * Steps are executed in order because a step's result can depend on the ones
364	 * before it: the count of contracts already issued decides the follow-up
365	 * discount, and the policies a quote registers are what later claims draw on.
366	 */
367	export const runScenario = (scenario: Scenario): ScenarioResult => {
368	  let previousContracts = 0;
369	  const policies = new Map<number, Policy>();
370	
371	  const results = scenario.steps.map((step, index): StepResult => {
372	    if (step.op === "claim") {
373	      // Unguarded: no test yet describes a claim naming a policy that was never
374	      // quoted. The "claim references an item/policy not in the policy" test
375	      // will force this honest.
376	      const policy = policies.get(step.policy) as Policy;
377	      return settleClaim(policy, step.incident);
378	    }
379	
380	    const premium = premiumFor(
381	      { customer: scenario.customer, previousContracts },
382	      step.items,
383	    );
384	    policies.set(index, policyFor(step.items));
385	    // Counted after pricing, so a quote never discounts itself, and only for
386	    // quotes, because a claim does not issue a contract.
387	    previousContracts += 1;
388	    return { premium };
389	  });
390	  return { results };
391	};
